const state={page:location.hash.slice(1)||'home',view:null,record:null,query:'',search:'',panel:null,comments:[],resolved:false,commentBlock:null,reply:null,calendar:new Date(2026,8,1),navOpen:false,expanded:new Set(['home']),recent:[],undo:[],redo:[],renderQueued:false,composing:false,ready:false,presence:[],gpu:null,zoom:30,timelineOffset:0,tableStart:0,activeEditor:null,baseline:new Map(),status:'Opening workspace…',readonly:false};
const sync=new (runtime.mode==='local'?LocalWorkspaceSync:WorkspaceSync)(status=>{state.status=status;let el=$('.save-label');if(el)el.textContent=status;updateOfflineBanner()});const r=sync.replica;
let session;
function toast(message){$('#toast').innerHTML=`<div class="toast">${esc(message)}</div>`;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').innerHTML='',4200)}
function updateOfflineBanner(){let off=state.status.startsWith('Offline')||state.status.startsWith('Access')||state.status.includes('error'),banner=$('.error-banner');if(off&&!banner){let div=document.createElement('div');div.className='error-banner';div.textContent=state.status;$('.main')?.insertBefore(div,$('.scroll-area'))}else if(banner){if(off)banner.textContent=state.status;else banner.remove()}}
