function property(rec,p,depth=0){if(p.type==='formula'){try{return evaluateFormula(p.formula||'0',Object.fromEntries(props(rec.db).filter(x=>x.type!=='formula'&&x.type!=='rollup').map(x=>[x.name,rec['prop:'+x.id]])))}catch{return 'Formula error'}}if(p.type==='rollup'){if(depth>2)return '';let ids=rec['prop:'+p.relation]||[];if(!Array.isArray(ids))ids=[ids];let vals=ids.map(id=>r.get(id)?.['prop:'+p.target]).filter(x=>x!=null);if(p.aggregate==='count')return ids.length;if(p.aggregate==='average')return vals.length?vals.reduce((a,b)=>a+Number(b||0),0)/vals.length:0;return vals.reduce((a,b)=>a+Number(b||0),0)}if(p.type==='created')return rec.created||'';return rec['prop:'+p.id]??''}
function remember(undo){if(typeof undo==='function'){state.undo.push(undo);if(state.undo.length>100)state.undo.shift();state.redo=[]}}
function setField(id,key,value){if(state.readonly)return;let prior=r.field(id,key),after=value;if(JSON.stringify(prior)===JSON.stringify(value))return;r.set(id,key,value);remember(()=>{r.set(id,key,prior??null);state.redo.push(()=>r.set(id,key,after))})}
function textEdit(id,field,text,baseline){if(state.readonly)return;let before=r.text(id,field),undo=r.edit(id,field,text,baseline);if(undo)remember(()=>{undo();state.redo.push(()=>r.edit(id,field,text))})}
const attr=(obj)=>Object.entries(obj).map(([k,v])=>`${k}="${esc(v)}"`).join(' ');
function rich(id,field='text'){return r.runs(id,field).map(run=>{let s=esc(run.text),m=run.marks;if(m.code)s=`<code class="inline-code">${s}</code>`;if(m.bold)s=`<strong>${s}</strong>`;if(m.italic)s=`<em>${s}</em>`;if(m.underline)s=`<u>${s}</u>`;if(m.strike)s=`<s>${s}</s>`;if(m.highlight)s=`<mark class="text-highlight">${s}</mark>`;if(m.link&&safeURL(m.link))s=`<a href="${esc(m.link)}" target="_blank" rel="noopener noreferrer">${s}</a>`;return s}).join('')}
function editable(id,field,cls='block-content',placeholder='Type / for commands'){state.baseline.set(id+':'+field,[...r.visible(id,field)]);return `<div class="${cls}" data-text="${esc(id)}" data-field="${field}" ${state.readonly?'':'contenteditable="true"'} role="textbox" aria-label="${esc(field==='title'?'Page title':'Block text')}" spellcheck="true" data-placeholder="${esc(placeholder)}">${rich(id,field)}</div>`}
function resolveURL(s){return sync.local&&String(s).startsWith('folio-asset:')?sync.assetURL(s):s}
function safeURL(s){if(sync.local&&/^folio-asset:[a-z0-9-]+$/i.test(String(s)))return Boolean(sync.assetURL(s));try{return ['http:','https:','mailto:'].includes(new URL(s,location.origin).protocol)}catch{return false}}
function openPage(id){$('.record-sheet')?.remove();$('.side-panel')?.remove();state.record=null;state.page=id;state.view=null;state.query='';state.tableStart=0;state.panel=null;state.navOpen=false;location.hash=id;state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,8);localStorage.setItem('folio-recent',JSON.stringify(state.recent));render();if($('.scroll-area'))$('.scroll-area').scrollTop=0;presence();}
function navPage(p,level=0){if(level>12)return '';let children=r.all('page').filter(x=>x.parent===p.id),active=p.id===state.page;return `<div class="page-nav ${active?'active':''}" draggable="${!state.readonly}" data-page-drag="${p.id}"><button class="nav-row ${active?'active':''}" data-action="navigate" data-id="${p.id}" style="padding-left:${9+level*13}px"><span>${esc(p.icon||'📄')}</span><span class="nav-title">${esc(p.title||'Untitled')}</span></button><div class="row-actions">${children.length?ib('chevron','expand-page','Expand page',`data-id="${p.id}"`):''}${ib('plus','new-subpage','Add subpage',`data-id="${p.id}"`)}</div></div>${state.expanded.has(p.id)?children.map(c=>navPage(c,level+1)).join(''):''}`}
function sidebar(){let pages=r.all('page'),favorites=pages.filter(p=>p.favorite);return `<aside class="sidebar ${state.navOpen?'open':''}"><div class="brand-row"><img class="brand-mark" src="./favicon.svg" alt=""><span class="brand-name">Folio</span><span style="flex:1"></span>${ib('menu','toggle-sidebar','Collapse sidebar')}</div><button class="workspace-switch" data-action="workspace-menu"><span class="workspace-initial">${esc(initials(session.workspace.name).slice(0,1))}</span><span class="nav-title">${esc(session.workspace.name)}</span>${icon('down')}</button><button class="nav-row" data-action="search">${icon('search')}<span>Search</span><span class="shortcut">⌘ K</span></button><button class="nav-row ${state.page==='home'?'active':''}" data-action="navigate" data-id="home">${icon('home')}<span>Home</span></button><button class="nav-row" data-action="inbox">${icon('inbox')}<span>Inbox</span></button><div class="sidebar-scroll"><div class="nav-heading">Favorites</div>${favorites.map(p=>navPage(p)).join('')}<div class="nav-heading">Workspace${ib('plus','new-page','Add a page')}</div>${pages.filter(p=>!p.parent&&p.id!=='home').map(p=>navPage(p)).join('')}${button('Add a page','new-page','plus','nav-row')}</div><div class="sidebar-bottom">${button('Templates','templates','template','nav-row')}${button('Import','import','download','nav-row')}${button('Settings & members','settings','settings','nav-row')}${button('Trash','trash','trash','nav-row')}<div class="sidebar-user">${avatar(session.user.name)}<span class="nav-title">${esc(session.user.name)}</span>${ib(document.body.classList.contains('dark')?'sun':'moon','theme','Toggle appearance')}</div></div></aside>`}
function topbar(p){let parentPage=r.get(p.parent);return `<header class="topbar"><button class="icon-button mobile-menu" data-action="toggle-sidebar" aria-label="Open sidebar">${icon('menu')}</button><div class="breadcrumb">${parentPage?button(parentPage.title,'navigate','','',`data-id="${parentPage.id}"`)+`<span class="quiet">/</span>`:`<button data-action="navigate" data-id="home">${esc(session.workspace.name)}</button><span class="quiet">/</span>`}<span>${esc(p.icon||'📄')}</span><span>${esc(p.title||'Untitled')}</span></div><div class="top-actions"><span class="save-label">${esc(state.status)}</span>${sync.local?'<span class="small quiet" title="Data is stored only in this browser">On this device</span>':''}<div class="presence">${state.presence.slice(0,4).map(x=>avatar(x.name)).join('')}</div>${button('Share','share','','share-button')}${ib('comment','comments','Comments')}${ib('clock','history','Page history')}${ib('star','favorite',p.favorite?'Remove from favorites':'Add to favorites',p.favorite?'style="color:#bb9451"':'')}${ib('more','page-menu','Page options')}</div></header>`}
function pageHeader(p){return `${p.cover?`<div class="cover ${esc(p.cover)}"><div class="cover-actions">${button('Change cover','cover')}</div></div>`:''}<article class="page ${p.fullWidth||p.kind==='database'?'full-width':''} ${p.cover?'':'no-cover'} font-${esc(p.font||'default')}" data-page="${p.id}"><button class="page-icon" data-action="emoji" aria-label="Change page icon">${esc(p.icon||'📄')}</button><div class="page-tools">${button('Add icon','emoji')}${button(p.cover?'Change cover':'Add cover','cover')}${button('Add comment','comments')}</div>${editable(p.id,'title','page-title','Untitled')}${state.readonly?`<div class="read-only">${icon('lock')} You have ${esc(session.user.role)} access to this workspace.</div>`:''}`}
function homeContent(p){let jump=['projects','wiki','notes'].map(id=>r.get(id)).filter(Boolean);return `<p class="home-subtitle">A place for everything you’re working on. And everything that’s next.</p><div class="section-label">${icon('clock')} Jump back in</div><div class="jump-grid">${jump.map(x=>`<button class="jump-card" data-action="navigate" data-id="${x.id}"><span class="card-icon">${esc(x.icon)}</span>${icon('external')}<strong>${esc(x.title)}</strong><span class="small">${x.kind==='database'?`${records(x.id).length} projects · Your shared work`:'Your shared workspace'}</span></button>`).join('')}</div><div class="home-columns"><div>${renderBlocks(p.id)}</div><aside class="note-card"><span style="font-size:25px">🌱</span><strong>A fresh start, every day.</strong>Good ideas need a place to grow. Capture a thought, start a project, or make this space your own.<button data-action="templates">Explore templates ${icon('arrow')}</button></aside></div><div class="home-footer">${icon('people')} A little more connected. A lot more possible.<span style="flex:1"></span><span>Made for your team.</span></div>`}
function renderBlocks(pid){let list=blocks(pid);return `<div class="editor" data-editor="${pid}">${list.map((b,i)=>renderBlock(b,i)).join('')}${!state.readonly?`<button class="block-actions-footer" data-action="append-block" data-page="${pid}">+ <span>Click to add a block, or type / for commands</span></button>`:''}</div>`}
function renderBlock(b,i){let expanded=state.toggleOpen?.has(b.id)?state.toggleOpen.get(b.id):b.open;let handle=state.readonly?'':`<div class="block-handle">${ib('plus','insert-block','Insert block',`data-id="${b.id}"`)}<button draggable="true" data-drag="${b.id}" data-action="block-menu" data-id="${b.id}" aria-label="Move or edit block" title="Drag to move · click for options">${icon('grip')}</button></div>`,content=editable(b.id,'text'),special='',prefix='';
 if(b.style==='todo')prefix=`<input type="checkbox" data-check="${b.id}" aria-label="Complete task" ${b.checked?'checked':''} ${state.readonly?'disabled':''}>`;
 if(b.style==='bullet')prefix='<span class="bullet-mark">•</span>';
 if(b.style==='number')prefix=`<span class="bullet-mark">${i+1}.</span>`;
 if(b.style==='callout')prefix=`<span>${esc(b.emoji||'💡')}</span>`;
 if(b.style==='toggle')prefix=ib(expanded?'down':'chevron','toggle-block','Toggle content',`data-id="${b.id}"`);
 if(b.style==='divider')content='<hr>';
 if(b.style==='code')special='<span class="code-language">Plain text</span>';
 if(b.style==='image')content=b.url&&safeURL(b.url)?`<img src="${esc(resolveURL(b.url))}" alt="${esc(b.text||'Page image')}" loading="lazy"><div class="image-caption">${editable(b.id,'text','block-content','Add a caption')}</div>`:button('Add an image','image','image','file-block',`data-id="${b.id}"`);
 if(b.style==='file')content=b.url&&safeURL(b.url)?`<a class="file-block" href="${esc(resolveURL(b.url))}" download rel="noopener">${icon('file')} ${esc(b.name||'Download attachment')} ${icon('download')}</a>`:button('Upload a file','file','upload','file-block',`data-id="${b.id}"`);
 if(b.style==='link'){let target=r.get(b.target);content=target?`<button class="page-link" data-action="navigate" data-id="${target.id}">${esc(target.icon||'📄')} ${esc(target.title||'Untitled')}</button>`:button('Link to a page','link-page','link','file-block',`data-id="${b.id}"`)}
 if(b.style==='database'){let db=r.get(b.target);content=db?`<button class="page-link" data-action="navigate" data-id="${db.id}">${icon('table')} ${esc(db.title)}</button><div class="small quiet">${records(db.id).length} records · Open to edit all database views</div>`:button('Choose a database','link-database','table','file-block',`data-id="${b.id}"`)}
 return `<div class="block ${esc(b.style||'paragraph')} ${b.checked?'checked':''} ${b.indent?'nested':''}" data-block="${b.id}" style="${b.indent?`margin-left:${b.indent*28}px`:''}">${handle}${prefix}${content}${special}</div>${b.style==='toggle'&&expanded?`<div class="toggle-body"><div contenteditable="${!state.readonly}" data-detail="${b.id}" role="textbox" aria-label="Toggle content">${esc(b.detail||'Add content inside this toggle…')}</div></div>`:''}`}
function render(){if(!session||!state.ready)return;let focus=captureFocus(),scroll=$('.scroll-area')?.scrollTop||0;state.gpu?.destroy();state.gpu=null;let p=page();document.title=(p?.title||'Workspace')+' — Folio';if(!p||p.deleted){state.page='home';p=page()}$('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar(p)}<div class="scroll-area">${pageHeader(p)}${p.kind==='home'?homeContent(p):p.kind==='database'?`${p.description?`<p class="page-description">${esc(p.description)}</p>`:''}${database(p)}`:`${p.description?`<p class="page-description">${esc(p.description)}</p>`:''}${renderBlocks(p.id)}${renderBacklinks(p.id)}`}</article></div></main></div>`;$('.scroll-area').scrollTop=scroll;updateOfflineBanner();if(state.record)renderRecord();restoreFocus(focus);if(p.kind==='database')initDatabase();if(state.panel==='comments')renderComments();}
function scheduleRender(){if(!state.ready||state.renderQueued)return;state.renderQueued=true;requestAnimationFrame(()=>{state.renderQueued=false;if(state.composing){state.needsRender=true;return}render()})}
r.on(ops=>{if(!state.ready||!ops.length)return;if(ops.every(op=>op.kind!=='set'&&op.field==='text')){state.textDirty??=new Set();for(let op of ops)state.textDirty.add(op.entity);if(state.textPatchQueued)return;state.textPatchQueued=true;requestAnimationFrame(()=>{state.textPatchQueued=false;if(state.composing){state.needsRender=true;return}let focus=captureFocus();for(let id of state.textDirty){let target=$(`[data-text="${id}"][data-field="text"]`);if(target){let html=rich(id);if(target.innerHTML!==html)target.innerHTML=html;state.baseline.set(id+':text',[...r.visible(id,'text')])}}state.textDirty.clear();restoreFocus(focus)})}else scheduleRender()});
function captureFocus(){let el=document.activeElement;if(!el)return null;if(el.dataset.text){let sel=getSelection(),range=sel.rangeCount?sel.getRangeAt(0):null;if(!range||!el.contains(range.startContainer))return {id:el.dataset.text,field:el.dataset.field,offset:0};let pre=range.cloneRange();pre.selectNodeContents(el);pre.setEnd(range.startContainer,range.startOffset);let index=Array.from(pre.toString()).length,nodes=state.baseline.get(el.dataset.text+':'+el.dataset.field)||r.visible(el.dataset.text,el.dataset.field);let endPre=range.cloneRange();endPre.selectNodeContents(el);endPre.setEnd(range.endContainer,range.endOffset);let endIndex=Array.from(endPre.toString()).length;return {id:el.dataset.text,field:el.dataset.field,anchor:nodes[index-1]?.id,index,endAnchor:nodes[endIndex-1]?.id,endIndex,offset:pre.toString().length}}if(el.dataset.detail){let range=getSelection().rangeCount?getSelection().getRangeAt(0):null,offset=0;if(range){let pre=range.cloneRange();pre.selectNodeContents(el);pre.setEnd(range.startContainer,range.startOffset);offset=pre.toString().length}return {detail:el.dataset.detail,offset}}if(el.dataset.value)return {input:el.dataset.value,prop:el.dataset.prop,start:el.selectionStart,end:el.selectionEnd,draft:el.value,checked:el.checked};return null}
