function board(db,view,rows){let property=props(db.id).find(p=>p.id===view.group)||props(db.id).find(p=>p.type==='status')||props(db.id)[0],key=property?.id||'status',groups=[...new Set([...(property?.options||[]),...rows.map(x=>String(x.values[key]||'No status'))])];return `<div class="board">${groups.map(g=>{let group=rows.filter(x=>String(x.values[key]||'No status')===g);return `<section class="board-column" data-group="${esc(g)}" data-group-prop="${key}"><div class="board-heading">${tag(g)}<span class="quiet">${group.length}</span>${ib('plus','new-record','Add record',`data-group="${esc(g)}" data-prop="${key}"`)}</div>${group.map(x=>`<article class="board-card" draggable="${!state.readonly}" data-record-drag="${x.id}" data-action="open-record" data-id="${x.id}" tabindex="0" role="button"><div class="board-card-title">${esc(x.icon||'📄')}<span>${esc(x.title)}</span></div>${tag(x.values.priority)}${x.values.progress?`<div class="progress-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.values.progress)))}%"></span></div>`:''}<div class="board-card-footer"><span class="small quiet">${esc(x.values.date||'No date')}</span>${avatar(x.values.owner||'Unassigned')}</div></article>`).join('')}${button('New page','new-record','plus','board-add',`data-group="${esc(g)}" data-prop="${key}"`)}</section>`}).join('')}</div>`}
