function initDatabase(){let db=page(),v=currentView(db.id),rows=shownRecords(db.id);if(v.layout==='table'&&rows.length>80){let el=$('.table-wrap');el.scrollTop=state.tableScroll||0;el.addEventListener('scroll',()=>{let start=Math.max(0,Math.floor(el.scrollTop/42)-5);state.tableScroll=el.scrollTop;if(Math.abs(start-state.tableStart)>5){state.tableStart=start;$('.db-view').innerHTML=table(db,v,rows);initDatabase()}})}if(['timeline','chart'].includes(v.layout))initScene(db,v,rows)}
