function selectOptions(options,value){return options.map(x=>`<option value="${esc(typeof x==='string'?x:x[0])}" ${(typeof x==='string'?x:x[0])===value?'selected':''}>${esc(typeof x==='string'?x:x[1])}</option>`).join('')}
