function isDescendant(id,parent){let seen=new Set();while(id&&!seen.has(id)){seen.add(id);id=r.field(id,'parent');if(id===parent)return true}return false}
function selectedText(){let sel=getSelection();if(!sel.rangeCount||sel.isCollapsed)return null;let range=sel.getRangeAt(0),el=range.startContainer.parentElement?.closest('[data-text]');if(!el||!el.contains(range.endContainer))return null;let pre=range.cloneRange();pre.selectNodeContents(el);pre.setEnd(range.startContainer,range.startOffset);let start=Array.from(pre.toString()).length;return {id:el.dataset.text,field:el.dataset.field,start,end:start+Array.from(range.toString()).length,rect:range.getBoundingClientRect()}}
function applyFormat(mark){if(state.readonly)return;let s=selectedText()||state.savedSelection;if(!s)return;let t=r.textState(s.id,s.field),nodes=r.visible(s.id,s.field).slice(s.start,s.end),enabled=nodes.length>0&&nodes.every(n=>t.formats.get(n.id)?.get(mark)?.value);r.format(s.id,s.field,s.start,s.end,{[mark]:!enabled});closeMenu();state.savedSelection=null}
function selectionToolbar(){if(state.readonly||state.composing||$('.dialog'))return;let s=selectedText();$('.format-toolbar')?.remove();if(!s)return;state.savedSelection=s;let el=document.createElement('div');el.className='format-toolbar';el.style.left=Math.max(10,Math.min(s.rect.left,innerWidth-260))+'px';el.style.top=Math.max(8,s.rect.top-43)+'px';el.innerHTML=`<button data-action="format" data-mark="bold" aria-label="Bold"><b>B</b></button><button data-action="format" data-mark="italic" aria-label="Italic"><i>I</i></button><button data-action="format" data-mark="underline" aria-label="Underline"><u>U</u></button><button data-action="format" data-mark="strike" aria-label="Strikethrough"><s>S</s></button><button data-action="format" data-mark="code" aria-label="Inline code">${icon('code')}</button><button data-action="format" data-mark="highlight" aria-label="Highlight">A</button><button data-action="format-link" aria-label="Add link">${icon('link')}</button>`;document.body.append(el)}
document.addEventListener('mousedown',e=>{if(e.target.closest('.format-toolbar'))e.preventDefault();if(!e.target.closest('.menu,.format-toolbar,[data-action="block-menu"],[data-action="page-menu"]'))closeMenu()});
