document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message));return}if(e.target.classList.contains('dialog-backdrop'))closeModal()});
document.addEventListener('focusin',e=>{if(e.target.dataset.text){state.activeEditor=e.target.dataset.text;state.baseline.set(e.target.dataset.text+':'+e.target.dataset.field,[...r.visible(e.target.dataset.text,e.target.dataset.field)]);presence()}});
