function handleTextInput(el){if(!el.dataset.text||state.composing||state.readonly)return;let id=el.dataset.text,field=el.dataset.field,text=el.innerText.replace(/\r\n/g,'\n');let before=state.baseline.get(id+':'+field);textEdit(id,field,text,before);state.baseline.set(id+':'+field,[...r.visible(id,field)]);if(field==='text'&&text.startsWith('/')&&!text.includes('\n')){clearTimeout(state.slashTimer);state.slashTimer=setTimeout(()=>slash(id,$(`[data-block="${id}"]`),text.slice(1)),40)}else if(state.slash)closeMenu();queueSnapshot(r.field(id,'page')||id);}
document.addEventListener('input',e=>{let el=e.target;if(el.dataset.text){handleTextInput(el);return}if(el.id==='workspace-search'){$('#workspace-results').innerHTML=searchResults(el.value);return}if(el.classList.contains('db-search')){state.query=el.value;state.tableStart=0;let db=page(),v=currentView(db.id);state.gpu?.destroy();$('.db-view').innerHTML=dbView(db,v,shownRecords(db.id));initDatabase();return}if(el.hasAttribute('data-timeline-zoom')){state.zoom=Number(el.value);let db=page();state.gpu?.destroy();initScene(db,currentView(db.id),shownRecords(db.id));return}if(el.dataset.detail)setField(el.dataset.detail,'detail',el.innerText)});
document.addEventListener('change',async e=>{let el=e.target;try{if(el.dataset.check)setField(el.dataset.check,'checked',el.checked);if(el.dataset.value){let rec=r.get(el.dataset.value),p=props(rec.db).find(p=>p.id===el.dataset.prop);let value=p.type==='checkbox'?el.checked:p.type==='number'?(el.value===''?null:Number(el.value)):el.value;setField(rec.id,'prop:'+p.id,value);queueSnapshot(rec.db)}if(el.id==='appearance'){applyTheme(el.value);render()}if(el.dataset.member){await sync.api('members',{method:'PATCH',body:JSON.stringify({user:el.dataset.member,role:el.value})});toast('Access updated')}}catch(err){toast(err.message)}});
document.addEventListener('paste',e=>{let el=e.target.closest('[data-text]');if(!el||state.readonly)return;e.preventDefault();let text=e.clipboardData.getData('text/plain'),sel=getSelection();if(!sel.rangeCount)return;let range=sel.getRangeAt(0);range.deleteContents();let node=document.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);sel.removeAllRanges();sel.addRange(range);handleTextInput(el)});
document.addEventListener('keydown',e=>{let el=e.target,editableEl=el.closest('[data-text]'),mod=e.metaKey||e.ctrlKey;
 if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();return}
 if(e.key==='Escape'){closeMenu();if($('.dialog-backdrop'))closeModal();else if(state.record){state.record=null;$('.record-sheet')?.remove()}else if(state.panel){state.panel=null;$('.side-panel')?.remove()}return}
 if($('.dialog')&&e.key==='Tab'){let focusable=$$('button,input,select,textarea,a[href]',$('.dialog')).filter(el=>!el.disabled&&el.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&el===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&el===last){e.preventDefault();first?.focus()}return}
 if(el.tagName==='INPUT'&&el.id==='new-title'&&e.key==='Enter'){e.preventDefault();action('create-page',el);return}
 if(el.id==='workspace-search'&&e.key==='Enter'){e.preventDefault();$('#workspace-results [data-action]')?.click();return}
 if(state.slash&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){let items=$$('.slash-menu button');if(items.length){e.preventDefault();if(e.key==='Enter'){items[state.slash.index]?.click();return}state.slash.index=(state.slash.index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach((x,i)=>x.classList.toggle('selected',i===state.slash.index));items[state.slash.index].scrollIntoView({block:'nearest'});return}}
 if(mod&&e.key.toLowerCase()==='z'&&!state.readonly&&(editableEl||!['INPUT','TEXTAREA'].includes(el.tagName))){e.preventDefault();if(e.shiftKey){state.redo.pop()?.()}else{let undo=state.undo.pop(),count=state.redo.length;if(undo){undo();if(state.redo.length>count){let redo=state.redo.pop();state.redo.push(()=>{redo();state.undo.push(undo)})}}}return}
 if(!editableEl||state.readonly||state.composing)return;let id=editableEl.dataset.text,field=editableEl.dataset.field,b=r.get(id);
 if(mod&&['b','i','u'].includes(e.key.toLowerCase())){e.preventDefault();applyFormat({b:'bold',i:'italic',u:'underline'}[e.key.toLowerCase()]);return}
 if(e.key==='Enter'&&!e.shiftKey){if(b?.style==='code')return;e.preventDefault();if(field==='title'){let first=blocks(id)[0]?.id||newBlock(id);focusBlock(first,false);return}let sel=getSelection(),range=sel.rangeCount?sel.getRangeAt(0):null,text=editableEl.innerText,offset=text.length,endOffset=text.length;if(range){let pre=range.cloneRange();pre.selectNodeContents(editableEl);pre.setEnd(range.startContainer,range.startOffset);offset=pre.toString().length;let ending=range.cloneRange();ending.selectNodeContents(editableEl);ending.setEnd(range.endContainer,range.endOffset);endOffset=ending.toString().length}let before=text.slice(0,offset),after=text.slice(endOffset);if(!text&&['todo','bullet','number'].includes(b.style)){setField(id,'style','paragraph');return}let oldUndo=state.undo.length;r.edit(id,'text',before);let next=newBlock(b.page,id,['todo','bullet','number'].includes(b.style)?b.style:'paragraph',after);state.undo.length=oldUndo;remember(()=>{r.transact(()=>{r.edit(id,'text',text);r.set(next,'deleted',true)});state.redo.push(()=>r.transact(()=>{r.edit(id,'text',before);r.set(next,'deleted',false)}))});focusBlock(next,false);return}
 if(e.key==='Backspace'&&field==='text'){let range=getSelection().rangeCount?getSelection().getRangeAt(0):null;if(range?.collapsed){let pre=range.cloneRange();pre.selectNodeContents(editableEl);pre.setEnd(range.startContainer,range.startOffset);if(pre.toString().length===0){let list=blocks(b.page),index=list.findIndex(x=>x.id===id),prev=list[index-1];if(prev){e.preventDefault();let original=r.text(prev.id),suffix=r.text(id),n=original.length;r.edit(prev.id,'text',original+suffix);r.set(id,'deleted',true);remember(()=>{r.transact(()=>{r.edit(prev.id,'text',original);r.set(id,'deleted',false)});state.redo.push(()=>r.transact(()=>{r.edit(prev.id,'text',original+suffix);r.set(id,'deleted',true)}))});setTimeout(()=>{let target=$(`[data-text="${prev.id}"]`);target?.focus();if(target)setCaret(target,n)},40);return}}}}
 if(e.key==='Tab'&&field==='text'){e.preventDefault();setField(id,'indent',Math.max(0,Math.min(6,(b.indent||0)+(e.shiftKey?-1:1))));return}
 if(e.key===' '&&field==='text'){let text=r.text(id),style={'#':'heading1','##':'heading2','###':'heading3','-':'bullet','*':'bullet','1.':'number','[]':'todo','>':'quote','---':'divider'}[text];if(style){e.preventDefault();r.edit(id,'text','');setField(id,'style',style);focusBlock(id);return}}
});
let dragging=null;
document.addEventListener('dragstart',e=>{let block=e.target.closest('[data-drag]'),record=e.target.closest('[data-record-drag]'),p=e.target.closest('[data-page-drag]');if(state.readonly){e.preventDefault();return}dragging=block?{type:'block',id:block.dataset.drag}:record?{type:'record',id:record.dataset.recordDrag}:p?{type:'page',id:p.dataset.pageDrag}:null;if(dragging){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('application/x-folio',JSON.stringify(dragging));closeMenu()}});
document.addEventListener('dragover',e=>{let target=e.target.closest('[data-block],[data-group-prop],[data-date-drop],[data-page-drag]');if(target&&dragging){e.preventDefault();$$('.drop-before,.dragover').forEach(x=>x.classList.remove('drop-before','dragover'));target.classList.add(target.classList.contains('board-column')?'dragover':'drop-before')}});
