document.addEventListener('drop',e=>{if(state.readonly)return;if(e.dataTransfer.files.length){let b=e.target.closest('[data-block]'),pid=state.record||state.page;let file=e.dataTransfer.files[0];if(b||e.target.closest('.editor')){e.preventDefault();let bid=newBlock(pid,b?.dataset.block,file.type.startsWith('image/')?'image':'file');sync.upload(file).then(asset=>{r.set(bid,'url',asset.url);r.set(bid,'name',asset.name);r.set(bid,'asset',asset.id);toast('File uploaded')}).catch(err=>toast(err.message))}return}if(!dragging)return;e.preventDefault();let block=e.target.closest('[data-block]'),group=e.target.closest('[data-group-prop]'),day=e.target.closest('[data-date-drop]'),p=e.target.closest('[data-page-drag]');if(dragging.type==='block'&&block&&block.dataset.block!==dragging.id){let b=r.get(block.dataset.block),list=blocks(b.page),i=list.findIndex(x=>x.id===b.id),prev=list[i-1];r.transact(()=>{setField(dragging.id,'page',b.page);setField(dragging.id,'order',prev?(prev.order+b.order)/2:b.order-100)})}if(dragging.type==='record'&&group)setField(dragging.id,'prop:'+group.dataset.groupProp,group.dataset.group);if(dragging.type==='record'&&day)setField(dragging.id,'prop:date',day.dataset.dateDrop);if(dragging.type==='page'&&p&&p.dataset.pageDrag!==dragging.id){if(isDescendant(p.dataset.pageDrag,dragging.id)){toast('A page cannot be moved into its own subpage.')}else{setField(dragging.id,'parent',p.dataset.pageDrag);state.expanded.add(p.dataset.pageDrag)}}dragging=null;$$('.drop-before,.dragover').forEach(x=>x.classList.remove('drop-before','dragover'))});
window.addEventListener('hashchange',()=>{let id=location.hash.slice(1);if(id&&id!==state.page)openPage(id)});
window.addEventListener('beforeunload',e=>{if(sync.unpersisted?.size){e.preventDefault();e.returnValue=''}});
async function presence(){if(!state.ready)return;try{let {members}=await sync.api('presence',{method:'POST',body:JSON.stringify({page:state.record||state.page,block:state.activeEditor})});state.presence=members;let el=$('.presence');if(el)el.innerHTML=members.filter(x=>x.page===(state.record||state.page)).slice(0,4).map(x=>avatar(x.name)).join('');}catch{}}
function queueSnapshot(id){if(state.readonly)return;state.dirtyPages??=new Set();state.dirtyPages.add(id);clearTimeout(state.snapshotTimer);state.snapshotTimer=setTimeout(async()=>{for(let pid of state.dirtyPages){try{await saveVersion('Autosaved version',pid);state.dirtyPages.delete(pid)}catch{}}},15000)}
async function init(){applyTheme(localStorage.getItem('folio-theme')||'Light');try{state.recent=JSON.parse(localStorage.getItem('folio-recent')||'[]');session=await sync.open();state.readonly=!['owner','editor'].includes(session.user.role);state.ready=true;let hash;try{hash=parent.location.hash.slice(1)}catch{}if(hash&&r.get(hash))state.page=hash;if(!r.get(state.page))state.page='home';render();presence();setInterval(()=>{presence();if(state.panel==='comments'&&!$('#comment-text')?.value)loadComments()},12000);window.folio={replica:r,openPage,createPage,createRecord,sync,exportWorkspace:()=>r.export(),getCurrentPage:()=>page()};registerTools();if(sync.local&&'serviceWorker'in navigator)navigator.serviceWorker.register('./pages-sw.js').catch(()=>{});}catch(e){$('#app').innerHTML=`<div class="boot"><img src="./favicon.svg" width="48" height="48" alt=""><h1>Welcome to Folio</h1><p>${esc(e.message)}</p>${e.signin?`<a class="primary" style="text-decoration:none" href="${esc(e.signin)}" target="_top">Sign in with ChatGPT</a>`:`<button class="primary" onclick="location.reload()">Try again</button>`}</div>`}}
function registerTools(){const context=document.modelContext||navigator.modelContext;if(!context?.registerTool)return;const register=(name,description,inputSchema,execute)=>context.registerTool({name,description,inputSchema,execute:async args=>({content:[{type:'text',text:JSON.stringify(await execute(args))}]})});register('folio_search','Search workspace pages and records by title',{type:'object',properties:{query:{type:'string'}},required:['query']},({query})=>r.all().filter(x=>['page','record'].includes(x.type)&&(x.title||'').toLowerCase().includes(query.toLowerCase())).map(x=>({id:x.id,title:x.title,type:x.type})));register('folio_read_page','Read a page and its blocks',{type:'object',properties:{id:{type:'string'}},required:['id']},({id})=>({page:r.get(id),blocks:blocks(id)}));register('folio_create_page','Create a document page in the current workspace',{type:'object',properties:{title:{type:'string'}},required:['title']},({title})=>{if(state.readonly)throw Error('Editor access required');let id=createPage(title);openPage(id);return {id,title}});register('folio_append_block','Append a text block to a page',{type:'object',properties:{page:{type:'string'},text:{type:'string'},style:{type:'string',enum:types.map(x=>x[0])}},required:['page','text']},({page,text,style='paragraph'})=>{if(state.readonly)throw Error('Editor access required');if(!r.get(page))throw Error('Page not found');return {id:newBlock(page,null,style,text)}})}
